# Generated by manage.py generate_test_cases.
from datetime import timedelta

from django.http import HttpResponse
from django.urls import reverse
from django.utils import timezone

from bloomerp.models.communication.instant_messaging import (
    IMConversation,
    IMConversationParticipant,
    IMMessage,
)
from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestConversationsComponent(BloomerpComponentTestCase):
    """Exercise saved conversation discovery without exposing nonmember history."""

    view_name = "components_im_conversations"

    def prepare_conversations(self, scenario: RequestScenario) -> None:
        """Create one visible conversation and one private conversation."""
        connection = None
        chat = IMConversation.objects.create(
            connection=connection, name="Visible discussion"
        )
        member = IMConversationParticipant.objects.create(
            conversation=chat, user=self.normal_user
        )
        IMMessage.objects.create(
            conversation=chat, sender=member, sequence=1, body="Find this message"
        )
        IMConversation.objects.create(connection=connection, name="Hidden discussion")
        self.detail_url = reverse(
            "components_conversation", kwargs={"conversation_id": chat.pk}
        )

    def prepare_older_unread_conversations(self, scenario: RequestScenario) -> None:
        """Put unread chats behind 100 newer chats containing only own messages."""
        for index in range(100):
            chat = IMConversation.objects.create(name=f"Recent read {index}")
            member = IMConversationParticipant.objects.create(
                conversation=chat, user=self.normal_user
            )
            IMMessage.objects.create(conversation=chat, sender=member, sequence=1)
        for has_read_position in (False, True):
            chat = IMConversation.objects.create(
                name=f"Older unread {has_read_position}",
                last_activity_at=timezone.now() - timedelta(days=1),
            )
            member = IMConversationParticipant.objects.create(
                conversation=chat, user=self.normal_user
            )
            sender = IMConversationParticipant.objects.create(
                conversation=chat, user=self.admin_user
            )
            root = IMMessage.objects.create(
                conversation=chat, sender=sender, sequence=1, body="Earlier message"
            )
            if has_read_position:
                member.last_read_message = root
                member.save(update_fields=["last_read_message"])
            IMMessage.objects.create(conversation=chat, sender=sender, sequence=2)
            IMMessage.objects.create(conversation=chat, sender=member, sequence=3)
            IMMessage.objects.create(
                conversation=chat, sender=sender, sequence=4, thread_root=root
            )
            IMMessage.objects.create(
                conversation=chat, sender=sender, sequence=5, deleted_at=timezone.now()
            )
        hidden = IMConversation.objects.create(name="Hidden unread")
        hidden_sender = IMConversationParticipant.objects.create(
            conversation=hidden, user=self.admin_user
        )
        IMMessage.objects.create(conversation=hidden, sender=hidden_sender, sequence=1)

    def validate_older_unread_results(self, response: HttpResponse) -> bool:
        """Check unread counts honor read positions, senders, deletion and threads."""
        rows = response.context["rows"]
        return {row["conversation"].name: row["unread"] for row in rows} == {
            "Older unread False": 2,
            "Older unread True": 1,
        } and response.context["unread_total"] == 3

    def validate_recent_results(self, response: HttpResponse) -> bool:
        """Keep the ordinary list limited while the unread total covers all chats."""
        rows = response.context["rows"]
        return (
            len(rows) == 100
            and all(row["conversation"].name.startswith("Recent read") for row in rows)
            and all(row["unread"] == 0 for row in rows)
            and response.context["unread_total"] == 3
        )

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Check membership scoping, message search, empty results and login."""
        return [
            RequestScenario(
                name="Unread filtering precedes the conversation limit",
                user=self.normal_user,
                prepare=self.prepare_older_unread_conversations,
                query_params={"unread": "1"},
                expected=ExpectedResult(
                    response_validators=[self.validate_older_unread_results]
                ),
            ),
            RequestScenario(
                name="Ordinary list retains its limit and complete unread total",
                user=self.normal_user,
                prepare=self.prepare_older_unread_conversations,
                expected=ExpectedResult(
                    response_validators=[self.validate_recent_results]
                ),
            ),
            RequestScenario(
                name="Member conversations link to reusable fragment",
                user=self.normal_user,
                prepare=self.prepare_conversations,
                expected=ExpectedResult(
                    response_validators=[
                        self.contains_text("Visible discussion"),
                        self.does_not_contain_text("Hidden discussion"),
                        self.contains_text('hx-target="#im-conversation-host"'),
                    ]
                ),
            ),
            RequestScenario(
                name="Message search finds conversation",
                user=self.normal_user,
                prepare=self.prepare_conversations,
                query_params={"q": "Find this"},
                expected=ExpectedResult(
                    response_validators=[self.contains_text("Visible discussion")]
                ),
            ),
            RequestScenario(
                name="Search cannot find private conversation",
                user=self.normal_user,
                prepare=self.prepare_conversations,
                query_params={"q": "Hidden"},
                expected=ExpectedResult(
                    response_validators=[
                        self.does_not_contain_text("Hidden discussion"),
                        self.contains_text("No conversations found."),
                    ]
                ),
            ),
            RequestScenario(
                name="Anonymous login required",
                expected=ExpectedResult(status_code=302),
            ),
        ]
